import pathlib, json, datetime

base = pathlib.Path("/mnt/e/codex-LOOP/codex-loop-s-f2")

# Look at host_close_observed events more deeply
lc_events_path = base / "data" / "lifecycle" / "events.ndjson"
with open(lc_events_path) as f:
    lines = f.readlines()

events = []
for line in lines:
    line = line.strip()
    if not line:
        continue
    try:
        events.append(json.loads(line))
    except:
        pass

print("=== host_close_observed full events ===")
for e in events:
    if e.get('event') == 'host_close_observed':
        print(json.dumps(e, indent=2))
        print()

