import pathlib

# Find .codex directory - might be in a different location
for candidate in [
    pathlib.Path("/mnt/c/Users/hzq00/.codex"),
    pathlib.Path("/home/codexloop/.codex"),
]:
    if candidate.exists():
        print(f"Found: {candidate}")
        try:
            items = sorted(candidate.iterdir())
            for item in items[:30]:
                sz = item.stat().st_size if item.is_file() else '-'
                print(f"  {'[D]' if item.is_dir() else f'[{sz}B]'} {item.name}")
        except Exception as e:
            print(f"  Error: {e}")
    else:
        print(f"Not found: {candidate}")

